"""Run SQL SELECT queries against CSV files."""

import csv
import os
import re
from collections import OrderedDict
from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP


class QueryError(Exception):
    """Raised for any problem with a query."""


_KEYWORDS = set("SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER LIMIT OFFSET AS ASC DESC AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE".split())
_TOKEN = re.compile(r"\s+|(?:--[^\n]*)|(?:'(?:(?:'')|[^'])*')|(?:\"(?:(?:\"\")|[^\"])*\")|(?:<=|>=|<>|!=|\|\|)|[(),.*+/<>=-]|[A-Za-z_][A-Za-z_0-9]*|[0-9]+(?:\.[0-9]*)?|\.[0-9]+")


@dataclass
class Tok:
    value: str
    start: int
    end: int


def _lex(sql):
    out = []
    p = 0
    while p < len(sql):
        m = _TOKEN.match(sql, p)
        if not m:
            raise QueryError("invalid character at position %d" % p)
        value = m.group()
        if not value.isspace() and not value.startswith("--"):
            out.append(Tok(value, p, m.end()))
        p = m.end()
    out.append(Tok("<EOF>", len(sql), len(sql)))
    return out


def _unquote_name(s):
    return s[1:-1].replace('""', '"') if s.startswith('"') else s


class Parser:
    def __init__(self, sql):
        self.sql, self.ts, self.i = sql, _lex(sql), 0

    @property
    def t(self): return self.ts[self.i]
    def upper(self): return self.t.value.upper()
    def take(self):
        t = self.t; self.i += 1; return t
    def accept(self, s):
        if self.upper() == s: return self.take()
        return None
    def need(self, s):
        t = self.accept(s)
        if not t: raise QueryError("expected %s" % s)
        return t
    def name(self):
        t = self.t
        if t.value.startswith('"'):
            self.take(); return _unquote_name(t.value)
        if re.fullmatch(r"[A-Za-z_][A-Za-z_0-9]*", t.value) and t.value.upper() not in _KEYWORDS:
            self.take(); return t.value
        raise QueryError("expected name")

    def query(self):
        self.need("SELECT"); distinct = bool(self.accept("DISTINCT"))
        cols = []
        if self.accept("*"):
            cols = [("star", None, None, self.ts[self.i-1].start, self.ts[self.i-1].end)]
        else:
            while True:
                start = self.t.start
                e = self.expr()
                alias = None
                if self.accept("AS"): alias = self.name()
                elif (self.t.value.startswith('"') or (re.fullmatch(r"[A-Za-z_][A-Za-z_0-9]*", self.t.value) and self.upper() not in _KEYWORDS)):
                    alias = self.name()
                end = self.ts[self.i-1].end
                cols.append(("expr", e, alias, start, end))
                if not self.accept(","): break
        self.need("FROM"); table = self.name()
        where = group = having = order = None; limit = offset = None
        if self.accept("WHERE"): where = self.expr()
        if self.accept("GROUP"):
            self.need("BY"); group = [self.expr()]
            while self.accept(","): group.append(self.expr())
        if self.accept("HAVING"): having = self.expr()
        if self.accept("ORDER"):
            self.need("BY"); order = []
            while True:
                e = self.expr()
                desc = bool(self.accept("DESC"))
                if not desc: self.accept("ASC")
                order.append((e, desc))
                if not self.accept(","): break
        if self.accept("LIMIT"):
            limit = self.integer()
            if self.accept("OFFSET"): offset = self.integer()
        if self.accept(";") is None and self.upper() != "<EOF>": raise QueryError("unexpected token %s" % self.t.value)
        if self.accept(";") and self.upper() != "<EOF>": raise QueryError("unexpected token %s" % self.t.value)
        return distinct, cols, table, where, group, having, order, limit, offset

    def integer(self):
        t = self.t
        if not re.fullmatch(r"[0-9]+", t.value): raise QueryError("LIMIT and OFFSET must be non-negative integers")
        self.take(); return int(t.value)

    def expr(self): return self.or_expr()
    def or_expr(self):
        x = self.and_expr()
        while self.accept("OR"): x = ("bin", "OR", x, self.and_expr())
        return x
    def and_expr(self):
        x = self.not_expr()
        while self.accept("AND"): x = ("bin", "AND", x, self.not_expr())
        return x
    def not_expr(self):
        if self.accept("NOT"): return ("un", "NOT", self.not_expr())
        return self.compare()
    def compare(self):
        x = self.concat()
        while True:
            op = self.upper()
            if op in ("=", "!=", "<>", "<", "<=", ">", ">="):
                self.take(); x = ("bin", op, x, self.concat()); continue
            if self.accept("IS"):
                neg = bool(self.accept("NOT")); self.need("NULL"); x = ("isnull", neg, x); continue
            neg = False
            if self.upper() == "NOT" and self.ts[self.i+1].value.upper() in ("IN", "BETWEEN", "LIKE"):
                self.take(); neg = True
            op = self.upper()
            if op == "IN":
                self.take(); self.need("("); args = []
                if self.upper() != ")":
                    args.append(self.expr())
                    while self.accept(","): args.append(self.expr())
                self.need(")"); x = ("in", neg, x, args); continue
            if op == "BETWEEN":
                self.take(); a = self.concat(); self.need("AND"); b = self.concat(); x = ("between", neg, x, a, b); continue
            if op == "LIKE":
                self.take(); x = ("like", neg, x, self.concat()); continue
            break
        return x
    def concat(self):
        x = self.add()
        while self.accept("||"): x = ("bin", "||", x, self.add())
        return x
    def add(self):
        x = self.mul()
        while self.upper() in ("+", "-"):
            op = self.take().value; x = ("bin", op, x, self.mul())
        return x
    def mul(self):
        x = self.unary()
        while self.upper() in ("*", "/"):
            op = self.take().value; x = ("bin", op, x, self.unary())
        return x
    def unary(self):
        if self.accept("-"): return ("un", "-", self.unary())
        return self.atom()
    def atom(self):
        t = self.t; u = self.upper()
        if self.accept("("):
            x = self.expr(); self.need(")"); return x
        if t.value.startswith("'"):
            self.take(); return ("lit", t.value[1:-1].replace("''", "'"))
        if u == "NULL": self.take(); return ("lit", None)
        if u in ("TRUE", "FALSE"): self.take(); return ("lit", u == "TRUE")
        if re.fullmatch(r"[0-9]+", t.value): self.take(); return ("lit", int(t.value))
        if re.fullmatch(r"(?:[0-9]+\.[0-9]*|\.[0-9]+)", t.value): self.take(); return ("lit", float(t.value))
        if t.value.startswith('"') or (re.fullmatch(r"[A-Za-z_][A-Za-z_0-9]*", t.value) and u not in _KEYWORDS):
            name = self.name()
            if self.accept("("):
                args = []
                if self.upper() != ")":
                    if self.accept("*"): args = [("star",)]
                    else:
                        args.append(self.expr())
                        while self.accept(","): args.append(self.expr())
                self.need(")"); return ("call", name.upper(), args)
            return ("name", name)
        raise QueryError("expected expression near %s" % t.value)


def _load(directory, table):
    path = os.path.join(os.fspath(directory), table + ".csv")
    try:
        with open(path, newline="", encoding="utf-8") as f:
            reader = csv.reader(f)
            try: header = next(reader)
            except StopIteration: raise QueryError("table %s has no header" % table)
            if len(set(x.lower() for x in header)) != len(header): raise QueryError("duplicate column name")
            rows = []
            for row in reader:
                if len(row) != len(header): raise QueryError("row has wrong number of fields")
                rows.append(tuple(_value(x) for x in row))
            return header, rows
    except QueryError: raise
    except OSError as e: raise QueryError("cannot read table %s: %s" % (table, e))


def _value(s):
    if s == "": return None
    if re.fullmatch(r"-?[0-9]+", s): return int(s)
    if re.fullmatch(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)", s): return float(s)
    return s


_AGGS = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
_SCALARS = {"LOWER", "UPPER", "LENGTH", "ABS", "ROUND", "COALESCE"}


def _contains_agg(e):
    if not isinstance(e, tuple): return False
    if e[0] == "call" and e[1] in _AGGS: return True
    return any(_contains_agg(x) for x in e[1:] if isinstance(x, tuple)) or (e[0] in ("in",) and any(_contains_agg(x) for x in e[3]))


def _names(e):
    if not isinstance(e, tuple): return []
    found = [e[1]] if e[0] == "name" else []
    for x in e[1:]:
        if isinstance(x, tuple): found += _names(x)
        elif isinstance(x, list):
            for y in x: found += _names(y)
    return found


def _truth(v): return v is True


def _compare(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        if type(a) is not type(b): raise QueryError("incompatible comparison")
    elif isinstance(a, (int, float)) and isinstance(b, (int, float)): pass
    elif isinstance(a, str) and isinstance(b, str): pass
    else: raise QueryError("incompatible comparison")
    return (a > b) - (a < b)


def _eval(e, row, headers, group=None):
    k = e[0]
    if k == "lit": return e[1]
    if k == "star": return None
    if k == "name":
        key = e[1].lower()
        if key not in headers: raise QueryError("unknown column %s" % e[1])
        return row[headers[key]]
    if k == "call":
        fn, args = e[1], e[2]
        if fn in _AGGS:
            if group is None: raise QueryError("aggregate outside grouped query")
            if fn == "COUNT" and len(args) == 1 and args[0][0] == "star": return len(group)
            if len(args) != 1: raise QueryError("%s expects one argument" % fn)
            vals = [_eval(args[0], r, headers, None) for r in group]
            vals = [v for v in vals if v is not None]
            if fn == "COUNT": return len(vals)
            if not vals: return None
            if fn == "SUM":
                if any(isinstance(v, bool) or not isinstance(v, (int, float)) for v in vals): raise QueryError("SUM requires numbers")
                return sum(vals)
            if fn == "AVG":
                if any(isinstance(v, bool) or not isinstance(v, (int, float)) for v in vals): raise QueryError("AVG requires numbers")
                return float(sum(vals) / len(vals))
            result = vals[0]
            for v in vals[1:]: result = v if _compare(v, result) < 0 and fn == "MIN" or _compare(v, result) > 0 and fn == "MAX" else result
            return result
        if fn not in _SCALARS: raise QueryError("unknown function %s" % fn)
        if fn == "COALESCE":
            if not args: raise QueryError("COALESCE expects at least one argument")
            for a in args:
                v = _eval(a, row, headers, group)
                if v is not None: return v
            return None
        n = 2 if fn == "ROUND" else 1
        if len(args) not in ((1, 2) if fn == "ROUND" else (1,)): raise QueryError("wrong number of arguments for %s" % fn)
        vals = [_eval(a, row, headers, group) for a in args]
        if any(v is None for v in vals): return None
        v = vals[0]
        if fn in ("LOWER", "UPPER", "LENGTH"):
            if not isinstance(v, str): raise QueryError("%s requires a string" % fn)
            return {"LOWER": str.lower, "UPPER": str.upper, "LENGTH": len}[fn](v)
        if isinstance(v, bool) or not isinstance(v, (int, float)): raise QueryError("%s requires a number" % fn)
        if fn == "ABS": return abs(v)
        if len(vals) == 1:
            return int(Decimal(str(v)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        if isinstance(vals[1], bool) or not isinstance(vals[1], int): raise QueryError("ROUND places must be an integer")
        return float(Decimal(str(v)).quantize(Decimal(1).scaleb(-vals[1]), rounding=ROUND_HALF_UP))
    if k == "un":
        a = _eval(e[2], row, headers, group)
        if e[1] == "NOT": return None if a is None else not bool(a)
        if a is None: return None
        if isinstance(a, bool) or not isinstance(a, (int, float)): raise QueryError("unary minus requires a number")
        return -a
    if k == "isnull": return (_eval(e[2], row, headers, group) is None) != e[1]
    if k == "bin":
        op = e[1]; a = _eval(e[2], row, headers, group)
        if op == "AND":
            if a is False: return False
            b = _eval(e[3], row, headers, group)
            if b is False: return False
            return None if a is None or b is None else bool(a) and bool(b)
        if op == "OR":
            if a is True: return True
            b = _eval(e[3], row, headers, group)
            if b is True: return True
            return None if a is None or b is None else bool(a) or bool(b)
        b = _eval(e[3], row, headers, group)
        if a is None or b is None: return None
        if op in ("=", "!=", "<>", "<", "<=", ">", ">="):
            c = _compare(a, b)
            return {"=": c == 0, "!=": c != 0, "<>": c != 0, "<": c < 0, "<=": c <= 0, ">": c > 0, ">=": c >= 0}[op]
        if op == "||": return str(a) + str(b)
        if isinstance(a, bool) or isinstance(b, bool) or not isinstance(a, (int, float)) or not isinstance(b, (int, float)): raise QueryError("arithmetic requires numbers")
        if op == "/": return None if b == 0 else a / b
        return {"+": lambda: a+b, "-": lambda: a-b, "*": lambda: a*b}[op]()
    if k == "in":
        x = _eval(e[2], row, headers, group); vals = [_eval(a, row, headers, group) for a in e[3]]
        if x is None: v = None
        elif any(y is not None and _compare(x, y) == 0 for y in vals): v = True
        elif any(y is None for y in vals): v = None
        else: v = False
        return None if v is None else (not v if e[1] else v)
    if k == "between":
        x, a, b = (_eval(y, row, headers, group) for y in e[2:])
        v = None if x is None or a is None or b is None else (_compare(a, x) <= 0 and _compare(x, b) <= 0)
        return None if v is None else (not v if e[1] else v)
    if k == "like":
        a, b = _eval(e[2], row, headers, group), _eval(e[3], row, headers, group)
        if a is None or b is None: return None
        if not isinstance(a, str) or not isinstance(b, str): raise QueryError("LIKE requires strings")
        pattern = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in b)
        v = re.fullmatch(pattern, a, re.DOTALL) is not None
        return not v if e[1] else v
    raise QueryError("invalid expression")


def _format_expr(sql, span): return sql[span[0]:span[1]].strip()


def run(sql, directory="."):
    """Run ``sql`` against CSV files in ``directory`` and return columns and rows."""
    try:
        p = Parser(sql); parsed = p.query()
        distinct, cols, table, where, group_exprs, having, order, limit, offset = parsed
        header, source_rows = _load(directory, table)
        hmap = {x.lower(): i for i, x in enumerate(header)}
        if where and _contains_agg(where): raise QueryError("aggregates are not allowed in WHERE")
        filtered = [r for r in source_rows if where is None or _eval(where, r, hmap) is True]
        grouped = group_exprs is not None or any(_contains_agg(x[1]) for x in cols if x[0] == "expr") or _contains_agg(having) or any(_contains_agg(x) for x, _ in (order or []))
        if grouped:
            if group_exprs is None: groups = [filtered]
            else:
                d = OrderedDict()
                for r in filtered:
                    key = tuple(_eval(e, r, hmap) for e in group_exprs)
                    try: d.setdefault(key, []).append(r)
                    except TypeError: raise QueryError("unhashable GROUP BY value")
                groups = list(d.values())
            if group_exprs:
                allowed = {repr(e) for e in group_exprs}
                exprs = [x[1] for x in cols if x[0] == "expr"] + ([having] if having else []) + [e for e, _ in (order or [])]
                def check(e, inside=False):
                    if not isinstance(e, tuple): return
                    if e[0] == "call" and e[1] in _AGGS: return
                    if e[0] == "name" and repr(e) not in allowed: raise QueryError("column must appear in GROUP BY or aggregate")
                    for z in e[1:]:
                        if isinstance(z, tuple): check(z)
                        elif isinstance(z, list):
                            for a in z: check(a)
                for e in exprs: check(e)
            records = []
            for g in groups:
                base = g[0] if g else tuple(None for _ in header)
                if having is not None and _eval(having, base, hmap, g) is not True: continue
                vals = [_eval(e, base, hmap, g) for typ, e, _, _, _ in cols if typ == "expr"]
                records.append((vals, g, base))
        else:
            records = [([_eval(e, r, hmap) for typ, e, _, _, _ in cols if typ == "expr"], [r], r) for r in filtered]
        outcols = []; expr_positions = []
        for typ, e, alias, a, b in cols:
            if typ == "star": outcols.extend(header)
            else:
                expr_positions.append(len(outcols))
                if alias is not None: outcols.append(alias)
                elif e[0] == "name": outcols.append(header[hmap[e[1].lower()]] if e[1].lower() in hmap else e[1])
                else: outcols.append(_format_expr(sql, (a, b)))
        expanded = []
        for vals, g, base in records:
            if any(t[0] == "star" for t in cols): vals = list(base) + vals
            expanded.append([vals, g, base])
        # ORDER BY resolves output names, ordinals, or evaluates a source/group expression.
        if order:
            def order_value(rec, item):
                e, desc = item
                if e[0] == "lit" and isinstance(e[1], int):
                    n = e[1]
                    if n < 1 or n > len(outcols): raise QueryError("ORDER BY position out of range")
                    return rec[0][n-1]
                if e[0] == "name":
                    matches = [i for i, c in enumerate(outcols) if c.lower() == e[1].lower()]
                    if matches: return rec[0][matches[0]]
                return _eval(e, rec[2], hmap, rec[1] if grouped else None)
            # Stable sorts in reverse key priority, with explicit NULL placement.
            for item in reversed(order):
                desc = item[1]
                def cmp(a, b):
                    x, y = order_value(a, item), order_value(b, item)
                    if x is None or y is None:
                        c = 0 if x is y else (-1 if x is None else 1)
                    else: c = _compare(x, y)
                    return -c if desc else c
                from functools import cmp_to_key
                expanded.sort(key=cmp_to_key(cmp))
        if distinct:
            seen = set(); unique = []
            for rec in expanded:
                key = tuple(rec[0])
                if key not in seen: seen.add(key); unique.append(rec)
            expanded = unique
        start = offset or 0
        expanded = expanded[start:] if limit is None else expanded[start:start+limit]
        return Result(outcols, [tuple(x[0]) for x in expanded])
    except QueryError: raise
    except (ArithmeticError, TypeError, ValueError, IndexError) as e:
        raise QueryError(str(e))


@dataclass
class Result:
    columns: list
    rows: list
